test('decorateRequest accepts built-in request properties as dependencies', t => {
  t.plan(1)
  const fastify = Fastify()
  t.assert.doesNotThrow(
    () => fastify.decorateRequest('withDeps', null, ['id', 'params', 'raw', 'query', 'log', 'body'])
  )
})

test('decorateReply accepts built-in reply properties as dependencies', t => {
  t.plan(1)
  const fastify = Fastify()
  t.assert.doesNotThrow(
    () => fastify.decorateReply('withDeps', null, ['raw', 'request', 'log'])
  )
})

test('built-in properties are valid dependencies inside an encapsulated plugin', (t, done) => {
  t.plan(2)
  const fastify = Fastify()
  fastify.register(async (instance) => {
    instance.decorateRequest('scopedExtra', null, ['body', 'query'])
    instance.decorateReply('scopedReplyExtra', null, ['request'])
    t.assert.equal(instance.hasRequestDecorator('scopedExtra'), true)
  })
  fastify.ready((err) => {
    t.assert.ifError(err)
    done()
  })
})

test('dependencies can mix built-in properties and user decorators', t => {
  t.plan(1)
  const fastify = Fastify()
  fastify.decorateRequest('userDec', null)
  t.assert.doesNotThrow(
    () => fastify.decorateRequest('another', null, ['body', 'userDec'])
  )
})

test('unknown dependencies still throw FST_ERR_DEC_MISSING_DEPENDENCY', t => {
  t.plan(2)
  const fastify = Fastify()
  t.assert.throws(
    () => fastify.decorateRequest('withMissing', null, ['body', 'nonExistent']),
    (err) => err.code === 'FST_ERR_DEC_MISSING_DEPENDENCY'
  )
  // `body` exists on Request only, not on Reply
  t.assert.throws(
    () => fastify.decorateReply('withMissing', null, ['body']),
    (err) => err.code === 'FST_ERR_DEC_MISSING_DEPENDENCY'
  )
})
